// 安全离城按原有限预算穷尽合法安置；只读报价不占资源，不把未判定伪装成无解。
#include "siege_world.hpp"
#include "military_lifecycle.hpp"
#include "resident/model/common_operations.hpp"
#include <algorithm>
#include <map>
#include <set>
namespace hanmo::resident {
namespace {
// 查找沿输入次序借已有记录，预算失败保留原有额外返回字段。
template<class T>const T* get(const std::vector<T>& rows,const StableId& id){for(auto& r:rows)if(r.id==id)return &r;return nullptr;}
bool has(const std::vector<StableId>& rows,const StableId& id){return std::find(rows.begin(),rows.end(),id)!=rows.end();}
Outcome<SiegeDeparturePlan> failure(const StableId& army,const StableId& reason){Outcome<SiegeDeparturePlan> out;out.error=common_failure("SiegeSafeDepartureUnavailable").error;out.value.army_id=army;out.value.reason=reason;out.error.army_id=army;out.error.reason=reason;return out;}
Outcome<SiegeDeparturePlan> limit(const StableId& kind,Integer maximum){Outcome<SiegeDeparturePlan> out;out.error=common_failure("SiegeDeparturePlanningLimit").error;out.value.limit=kind;out.value.maximum=maximum;out.value.feasibility="undetermined";out.error.limit=kind;out.error.maximum=maximum;out.error.feasibility="undetermined";return out;}
}
// 本次仍未撤离的守军按稳定ID排序，保存重排不更换谈判队伍。
std::vector<StableId> siege_departure_defenders(const SiegeRecord& siege){std::vector<StableId> out;for(auto& p:siege.armies)if(p.second==1&&!has(siege.withdrawn_army_ids,p.first))out.push_back(p.first);std::sort(out.begin(),out.end());return out;}
// 选择最少优先只是剪枝；每个余量状态完整穷尽后才记无解，预算触顶即返回未判定。
Outcome<SiegeDeparturePlan> allocate_siege_departure(const std::vector<std::pair<StableId,std::vector<SiegeDepartureDestination>>>& plans,const std::vector<SiegeDepartureRoom>& rooms,Integer budget){if(plans.size()>16)return limit("armies",16);if(rooms.size()>32)return limit("camps",32);if(budget<0||budget>8192)return {false,{},common_failure("InvalidSiegeDepartureBudget").error};std::vector<StableId> order,camps;std::map<StableId,std::vector<SiegeDepartureDestination>> options;std::map<StableId,SiegeDepartureRoom> room,used;Integer total_weight=0,total_money=0,free_weight=0,free_money=0;for(auto& p:plans){if(p.second.empty())return failure(p.first,"CampaignNoFriendlyGarrison");order.push_back(p.first);options[p.first]=p.second;std::sort(options[p.first].begin(),options[p.first].end(),[](auto& a,auto& b){if(a.preferred!=b.preferred)return a.preferred;if(a.cost!=b.cost)return a.cost<b.cost;return a.garrison_id<b.garrison_id;});total_weight+=p.second[0].weight;total_money+=p.second[0].money;}std::sort(order.begin(),order.end(),[&](auto& a,auto& b){if(options[a].size()!=options[b].size())return options[a].size()<options[b].size();if(options[a][0].weight!=options[b][0].weight)return options[a][0].weight>options[b][0].weight;return a<b;});for(auto& r:rooms){camps.push_back(r.garrison_id);room[r.garrison_id]=r;used[r.garrison_id]={r.garrison_id,0,0};free_weight+=r.weight;free_money+=r.money;}std::sort(camps.begin(),camps.end());if(total_weight>free_weight)return failure("","GarrisonCapacityExceeded");if(total_money>free_money)return failure("","MoneyOverflow");std::map<StableId,SiegeDepartureDestination> selected;std::set<std::vector<Integer>> memo;Integer steps=0;std::function<Outcome<SiegeDeparturePlan>(std::size_t)> search=[&](std::size_t index)->Outcome<SiegeDeparturePlan>{if(index==order.size()){SiegeDeparturePlan out;for(auto& p:selected)out.destinations.push_back(p.second);return {true,out,{}};}std::vector<Integer> key{Integer(index)};for(auto& camp:camps){key.push_back(room[camp].weight-used[camp].weight);key.push_back(room[camp].money-used[camp].money);}if(memo.count(key))return failure("","SiegeReceptionCombinationUnavailable");if(steps>=budget)return limit("search_states",budget);++steps;auto army=order[index];for(auto& option:options[army]){auto found=room.find(option.garrison_id);if(found==room.end())return {false,{},common_failure("InvalidSiegeDepartureRequest").error};auto& capacity=found->second;auto& consumed=used[option.garrison_id];if(consumed.weight+option.weight>capacity.weight||consumed.money+option.money>capacity.money)continue;consumed.weight+=option.weight;consumed.money+=option.money;selected[army]=option;auto result=search(index+1);consumed.weight-=option.weight;consumed.money-=option.money;selected.erase(army);if(result.ok||result.error.original.code=="SiegeDeparturePlanningLimit")return result;}memo.insert(std::move(key));return failure("","SiegeReceptionCombinationUnavailable");};auto result=search(0);if(result.ok)result.value.search_states=steps;return result;}
// 每军先复用正式选营、公物归还及行旅报价，再按全队重量和金额求解，城内同城营地无资格。
Outcome<SiegeDeparturePlan> preview_siege_departure(const CommonRead& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitaryAccess& a,const SiegeRecord& siege){auto armies=siege_departure_defenders(siege);if(armies.empty())return failure("","SiegeDefenderRequired");if(armies.size()>16)return limit("armies",16);auto target=get(cat.strongholds,siege.stronghold_id);if(!target)return {false,{},common_failure("InvalidSiegeState").error};std::vector<std::pair<StableId,std::vector<SiegeDepartureDestination>>> plans;std::vector<SiegeDepartureRoom> room;std::vector<StableId> camps;for(auto& camp:cat.garrisons)camps.push_back(camp.id);std::sort(camps.begin(),camps.end());for(auto& army_id:armies){auto army=get(s.armies,army_id);auto campaign=army?get(s.campaigns,army->order_id):nullptr;if(!army||!campaign||army->status!="active"||campaign->army_id!=army_id||campaign->actor_id!=army->commander_actor_id||!has({"mustered","marching","operating","returning"},campaign->status))return failure(army_id,"CampaignCannotReturn");for(auto& member:army->member_actor_ids){auto person=c.actor(member);if(!person||!person->alive||!person->available||!person->action_id.empty())return failure(army_id,"ArmyMemberUnavailable");}for(auto& battle:s.battles)if(battle.phase!="closed")for(auto& unit:battle.units)if(has(army->unit_ids,unit.unit_id))return failure(army_id,"ArmyMustReturnToCamp");auto weight=c.inventory_weight(army->inventory_id);if(!weight.ok)return {false,{},weight.error};std::vector<SiegeDepartureDestination> options;StableId reason="CampaignNoFriendlyGarrison";for(auto& camp_id:camps){auto camp=get(cat.garrisons,camp_id);auto place=a.common_catalog?a.common_catalog->places.find(camp->place_id):nullptr;if(!place)return {false,{},common_failure("UnknownPlace",camp->place_id).error};if(place->settlement_id==target->settlement_id)continue;auto route=military_return_destination(c,s,cat,a,campaign->id,camp_id);if(!route.ok){if(route.error.kind!=ErrorKind::rule)return {false,{},route.error};reason=route.error.original.code;continue;}auto cargo=preview_military_return_assets(c,s,cat,army_id,camp_id);if(!cargo.ok){if(cargo.error.kind!=ErrorKind::rule)return {false,{},cargo.error};reason=cargo.error.original.code;continue;}if(!a.preview_travel)return {false,{},military_capability_failure("siege_safe_departure","preview_travel",army_id).error};auto travel=a.preview_travel(army->commander_actor_id,route.value.destination_settlement_id);if(!travel.ok){if(travel.error.kind!=ErrorKind::rule)return {false,{},travel.error};reason=travel.error.original.code;continue;}auto inventory=c.inventory(camp->inventory_id);auto wallet=c.wallet(camp->wallet_id);auto stored=c.inventory_weight(camp->inventory_id);if(!inventory||!wallet||!stored.ok)return {false,{},common_failure("MilitaryPublicAssetAuthority").error};SiegeDepartureRoom space{camp_id,inventory->capacity-stored.value,2147483647-wallet->balance};auto prior=std::find_if(room.begin(),room.end(),[&](auto& r){return r.garrison_id==camp_id;});if(prior==room.end())room.push_back(space);else *prior=space;if(room.size()>32)return limit("camps",32);options.push_back({army_id,campaign->id,camp_id,route.value.destination_settlement_id,route.value.cost,weight.value,cargo.value.money,camp_id==campaign->garrison_id});}if(options.empty())return failure(army_id,reason);plans.emplace_back(army_id,std::move(options));}auto allocated=allocate_siege_departure(plans,room);if(allocated.ok)allocated.value.army_ids=std::move(armies);return allocated;}
}
